import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

const Register: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phone: '',
    sponsorId: '',
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      await api.register(
        formData.email,
        formData.password,
        formData.name,
        formData.phone,
        formData.sponsorId || undefined
      );
      navigate('/dashboard');
    } catch (err: any) {
      setError(
        err.response?.data?.message || 
        err.message || 
        'Registration failed'
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex overflow-hidden relative">
      {/* Animated background elements */}
      <div className="absolute inset-0 overflow-hidden">
        <div className="absolute -top-40 -left-40 w-96 h-96 bg-emerald-500/10 rounded-full blur-3xl animate-pulse" />
        <div className="absolute -bottom-40 -right-40 w-96 h-96 bg-cyan-600/10 rounded-full blur-3xl animate-pulse" style={{ animationDelay: '1s' }} />
        <div className="absolute top-1/3 right-1/4 w-[500px] h-[500px] bg-blue-600/5 rounded-full blur-3xl animate-pulse" style={{ animationDelay: '2s' }} />
        {/* Grid pattern overlay */}
        <div className="absolute inset-0 opacity-[0.03]" style={{
          backgroundImage: 'linear-gradient(rgba(16,185,129,0.3) 1px, transparent 1px), linear-gradient(90deg, rgba(16,185,129,0.3) 1px, transparent 1px)',
          backgroundSize: '60px 60px',
        }} />
      </div>

      {/* Left side - Form */}
      <div className="flex-1 flex items-center justify-center p-6 relative z-10">
        <div className="w-full max-w-md">
          {/* Logo */}
          <div className="text-center mb-6">
            <div className="inline-flex items-center gap-3 mb-3">
              <div className="w-12 h-12 bg-gradient-to-r from-emerald-400 to-cyan-500 rounded-xl flex items-center justify-center font-bold text-xl text-white shadow-lg shadow-emerald-500/30">
                S
              </div>
              <h1 className="text-4xl font-bold bg-gradient-to-r from-emerald-400 to-cyan-500 bg-clip-text text-transparent">
                SERENVI
              </h1>
            </div>
            <p className="text-slate-500">Create your account & start earning</p>
          </div>

          {/* Form Card */}
          <div className="rounded-2xl border border-emerald-500/20 bg-slate-900/80 backdrop-blur-xl p-8 shadow-2xl shadow-emerald-500/5">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-slate-300 text-sm font-medium mb-1.5">Full Name</label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">👤</span>
                  <input
                    type="text"
                    name="name"
                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl pl-10 pr-4 py-3 text-slate-200 placeholder-slate-500 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/50 focus:outline-none transition-all"
                    placeholder="John Doe"
                    value={formData.name}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-slate-300 text-sm font-medium mb-1.5">Email Address</label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">📧</span>
                  <input
                    type="email"
                    name="email"
                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl pl-10 pr-4 py-3 text-slate-200 placeholder-slate-500 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/50 focus:outline-none transition-all"
                    placeholder="you@example.com"
                    value={formData.email}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-slate-300 text-sm font-medium mb-1.5">Phone Number</label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">📱</span>
                  <input
                    type="tel"
                    name="phone"
                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl pl-10 pr-4 py-3 text-slate-200 placeholder-slate-500 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/50 focus:outline-none transition-all"
                    placeholder="9876543210"
                    value={formData.phone}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-slate-300 text-sm font-medium mb-1.5">Password</label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">🔒</span>
                  <input
                    type="password"
                    name="password"
                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl pl-10 pr-4 py-3 text-slate-200 placeholder-slate-500 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/50 focus:outline-none transition-all"
                    placeholder="Create a strong password"
                    value={formData.password}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-slate-300 text-sm font-medium mb-1.5">Sponsor's Referral Code <span className="text-slate-600">(optional)</span></label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">🔗</span>
                  <input
                    type="text"
                    name="sponsorId"
                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl pl-10 pr-4 py-3 text-slate-200 placeholder-slate-500 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/50 focus:outline-none transition-all uppercase"
                    placeholder="e.g. A1B2C3"
                    value={formData.sponsorId}
                    onChange={handleChange}
                    maxLength={6}
                  />
                </div>
                <p className="text-xs text-slate-600 mt-1">Join your sponsor's network to earn commissions</p>
              </div>

              {error && (
                <div className="bg-red-500/10 border border-red-500/30 rounded-lg px-4 py-3 text-red-400 text-sm flex items-center gap-2">
                  <span>⚠️</span> {error}
                </div>
              )}

              <button
                type="submit"
                className="w-full py-3 bg-gradient-to-r from-emerald-500 to-cyan-600 text-white font-semibold rounded-xl hover:from-emerald-600 hover:to-cyan-700 transition-all shadow-lg shadow-emerald-500/25 hover:shadow-emerald-500/40 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:hover:scale-100"
                disabled={loading}
              >
                {loading ? (
                  <span className="flex items-center justify-center gap-2">
                    <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" /><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" /></svg>
                    Creating account...
                  </span>
                ) : 'Create Account →'}
              </button>
            </form>

            <div className="mt-5 pt-5 border-t border-slate-800">
              <p className="text-center text-slate-400 text-sm">
                Already have an account?{' '}
                <a href="/login" className="text-emerald-400 hover:text-emerald-300 font-semibold transition">
                  Sign in
                </a>
              </p>
            </div>
          </div>

          <p className="text-center text-slate-600 text-xs mt-6">
            © 2026 SERENVI. All rights reserved.
          </p>
        </div>
      </div>

      {/* Right side - Lottie Animation */}
      <div className="hidden lg:flex flex-1 items-center justify-center relative z-10">
        <div className="text-center space-y-6 px-12">
          {/* @ts-ignore */}
          <dotlottie-player
            src="https://lottie.host/5ac41ea7-830b-4e8e-b1f0-68b42b5a1995/uQUFJH4KoW.lottie"
            background="transparent"
            speed="1"
            style={{ width: '400px', height: '400px', margin: '0 auto' }}
            loop
            autoplay
          />
          <h2 className="text-4xl font-bold bg-gradient-to-r from-emerald-400 via-cyan-400 to-blue-500 bg-clip-text text-transparent">
            Join the Network
          </h2>
          <p className="text-slate-400 text-lg max-w-md mx-auto">
            Start your journey to financial independence. Build your team, sell premium products, and earn unlimited commissions.
          </p>
          {/* Feature highlights */}
          <div className="space-y-3 text-left max-w-sm mx-auto">
            <div className="flex items-center gap-3 bg-slate-900/50 border border-emerald-500/10 rounded-lg px-4 py-3">
              <span className="text-emerald-400 text-xl">💰</span>
              <div>
                <p className="text-slate-200 text-sm font-semibold">25% Direct Commission</p>
                <p className="text-slate-500 text-xs">On every sale from your referrals</p>
              </div>
            </div>
            <div className="flex items-center gap-3 bg-slate-900/50 border border-cyan-500/10 rounded-lg px-4 py-3">
              <span className="text-cyan-400 text-xl">📈</span>
              <div>
                <p className="text-slate-200 text-sm font-semibold">Leadership Salary</p>
                <p className="text-slate-500 text-xs">Monthly salary up to ₹50 Lakhs</p>
              </div>
            </div>
            <div className="flex items-center gap-3 bg-slate-900/50 border border-blue-500/10 rounded-lg px-4 py-3">
              <span className="text-blue-400 text-xl">🏆</span>
              <div>
                <p className="text-slate-200 text-sm font-semibold">Achievement Rewards</p>
                <p className="text-slate-500 text-xs">Unlock rewards as you grow your team</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Register;
